def no_links(file):
    for current in [file, *file.parents]:
        if current.is_symlink():
            raise ValueError('link')


def inspect():
    deadline = time.monotonic() + 30
    actual, issues, seen = {}, [], set()
    no_links(ROOT)
    def walk(directory, relative=''):
        for entry in os.scandir(directory):
            name = relative + '/' + entry.name if relative else entry.name
            if time.monotonic() > deadline:
                raise ValueError('timeout')
            if entry.is_symlink():
                issues.append('unapproved-link')
            elif entry.is_dir(follow_symlinks=False):
                if name.split('/')[0] not in {'src', 'public', 'manager-ui', 'scripts'}:
                    issues.append('unexpected-directory')
                else:
                    walk(entry.path, name)
            elif name not in FILES:
                issues.append('unexpected-file')  # Never open or emit unknown names/content.
    walk(ROOT)
    for name, variants in FILES.items():
        if time.monotonic() > deadline:
            raise ValueError('timeout')
        file = ROOT / name
        try:
            no_links(file)
            info = file.lstat()
            if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1 or info.st_size not in {v['bytes'] for v in variants}:
                issues.append(name + ':metadata-mismatch')
                continue
            descriptor = os.open(file, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
            try:
                before = os.fstat(descriptor)
                if before.st_ino != info.st_ino or before.st_dev != info.st_dev:
                    raise ValueError('changed')
                h = hashlib.sha256()
                with os.fdopen(descriptor, 'rb', closefd=False) as stream:
                    for block in iter(lambda: stream.read(65536), b''):
                        h.update(block)
                after = os.fstat(descriptor)
                if (before.st_size, before.st_mtime_ns, before.st_ctime_ns) != (after.st_size, after.st_mtime_ns, after.st_ctime_ns):
                    raise ValueError('changed')
                digest = h.hexdigest()
            finally:
                os.close(descriptor)
            if digest not in {v['sha256'] for v in variants}:
                issues.append(name + ':hash-mismatch')
            else:
                actual[name] = digest
        except (OSError, ValueError):
            issues.append(name + ':unavailable-or-link-or-drift')
    verified = len(actual) == 65 and not issues
    packet = json.dumps(actual, sort_keys=True, separators=(',', ':'), ensure_ascii=True).encode()
    return {'protocol': 'riftassist-legacy-source-1', 'readOnly': True,
            'baselineCommit': BASELINE_COMMIT, 'referenceSha256': REFERENCE_SHA256,
            'matchedCodeFiles': len(actual), 'referenceVerified': verified,
            'deploymentCodeHash': hashlib.sha256(packet).hexdigest() if verified else None,
            'issues': issues[:80], 'unknownFileNamesEmitted': False,
            'notRead': ['DB', 'keys', 'user records', 'Environment', 'logs', 'unknown file contents'],
            'authorizedToDeploy': False}


if __name__ == '__main__':
    try:
        print(json.dumps(inspect(), ensure_ascii=True, separators=(',', ':')))
    except Exception:
        print(json.dumps({'protocol': 'riftassist-legacy-source-1', 'readOnly': True,
                          'referenceVerified': False, 'error': 'code-metadata-unavailable',
                          'detailSuppressed': True, 'authorizedToDeploy': False}))
